#

from brian.audio import play_tone
import time
from brian.motors import EV3LargeMotor
from brian.motors import MotorPort
from brian.sensors.EV3 import GyroSensorEV3
from brian.sensors import SensorPort

HowFar_ = None
gyro = None
MotionCorrection = None
x = None
left = None
AngleDirection = None
right = None

def sensor_retry(sensor, call_fun):
  from brian.sensors import SensorIsNotReadyError
  while True:
    try:
      sensor.wait_until_ready()
      return call_fun()
    except SensorIsNotReadyError:
      # Čtení senzoru může selhat. Opakuj při chybě
      pass

def motor_retry(motor, call_fun):
  from brian.motors import MotorIsNotReadyError
  while True:
    try:
      motor.wait_until_ready()
      return call_fun()
    except MotorIsNotReadyError:
      # Ovládání motoru může selhat. Opakuj při chybě
      pass

# Skopčenej kod z minulého roku, je to nastavené
# na současné proporce, snad by to mělo fungovat
def DriveForward(HowFar_):
  global gyro, MotionCorrection, x, left, AngleDirection, right
  left = EV3LargeMotor(MotorPort.A)
  right = EV3LargeMotor(MotorPort.B)
  gyro = GyroSensorEV3(SensorPort.S1)
  sensor_retry(gyro, gyro.set_zero_point)
  while motor_retry(left, left.current_angle) <= x:
    MotionCorrection = sensor_retry(gyro, gyro.angle) - 4 * AngleDirection
    motor_retry(left, lambda: left.run_at_speed(360 + 18 * MotionCorrection))
    motor_retry(right, lambda: right.run_at_speed(360 + 18 * MotionCorrection))


print('Start')
play_tone(440, 1000)
time.sleep(1)
DriveForward(None)
print('Finish')

